"""Reconcile existing research archives before copying exact served XML."""
import hashlib, json, re, xml.etree.ElementTree as E
from pathlib import Path
slugs = ['fruit-wars', 'limited-order-book', 'bidding-market', 'hotellings-law', 'braess-paradox', 'cash-flow', 'bank-reserves', 'prisoners-dilemma-basic', 'prisoners-dilemma-two-person-iterated', 'el-farol']
inv=json.loads(Path('experiments/catalog/inventory.json').read_text())
selection=json.loads(Path('experiments/catalog/selection/selection.json').read_text())
tree={r['path']:r for r in json.loads(Path('experiments/catalog/pinned/galapagos-tree.json').read_text())['tree']}
notes={'fruit-wars': 'Wrapped 65x65. Forty bushes sampled from separated modulo-3 sites, amounts500+random501; forty foragers with240-bit genomes, energy100. Sequential random forager asks; fleeing branch excludes energy/reproduction, foraging drains bush10 but credits intelligence/group bonus; movement costs1. Arrival threats/fights can kill different membership from count-fighters: preserve source counters. Reproduction at energy>200 mutates bits, child resets age/energy/flags. Age>max-age dies. Death marks expire age>10. Empty population stops before any work. Bush growth n-of1 may fail if no eligible sites. Average population uses PRE-tick denominator and starts0; death-count unused. Source plot mean on extinct set can fail. Visualization/labels are presentation. Defaults and all plot equations below.', 'limited-order-book': 'Hard41x41,50 honest+50 cunning. Reusable two orders per trader, separate pending/removed/listed states and owner references. random amount is integer random(amount)*.5+amount*.5. Orders rebuilt each go; utility refreshed BEFORE matching (lagged). Random pending-order activation, strict ask<bid crossing, equal prices do not trade. Execution price min(bid,ask), affordable units floor(cash/price/unit)*unit, stock bound and remaining bound; cash/tokens conserved. Inserts equal prices ahead despite comment older-first. Cunning uses previous best quotes. Recent EWMA .1; price-to-date divides total-volume/total-amount without zero guard: source zero-trade scenario error retained explicitly. No terminal condition. Precision setup-only trade-unit; initial assets/counts setup-only.', 'bidding-market': 'Hard29x29,50 sellers and50 buyers, ordered rings and stable cyclic pairing offset1+ticks%50. Setup supply/demand even1+random amount or concentrated1+floor exponential(amount/2); high50/low25. Starting prices half plus integer randomhalf rounded cents. Preflight stops no supply or no solvent unmet buyer. Sequential fixed seller pairing, one item per success if ask<=cash and willingness. Transfer rounded cents, residual<.01 to0; adapt willingness capped cash. Normal seller +2.5/-2%, desperate+.7/-5; buyer normal-2/+2.5, desperate-.5/+7.5; random integer-5..5. Seller ignore-full switch suppresses no-sale change only for normal/desperate. remaining-supply is PRE-commerce. Source post-commerce affordability sanity error possible. Source formulas and widgets below; stars/shadows/drawing presentation.', 'hotellings-law': 'Hard41x41 consumer line x=0 or plane; random store sites, price10, colors without replacement. Consumer choice min(price+distance), random ties. Plan all location tasks from old configuration, then all price tasks from old configuration; execute all moves then prices, then recalculate shares and tick. Local faces moves only in consumer set; include current first only if positive market share. Hypothetical share evaluation consumes tie randomness but restores coordinates/prices. Price candidates current first then random +/-1, revenue share*price; all-zero emergency lowers if>1. No general positive-price clamp. Layout/count setup-only; rules live. No stop. Shares partition consumers; plots show current shares/prices not histories where source says so.', 'braess-paradox': 'Hard49x49, corners+/-22. Source-specific patch roads, no generic graph routing API required. Top/bottom route names and road-type comments disagree: actual road-type1 gets dynamic determine-congestion, initial delay5/base10, type0 fixed10. Source waiting strictly ticks-here>delay; departure records last-here, moves patch-ahead, reset1; turns and exit after movement/wait. spawn-time>250/spawn-rate (strict), spawn happens before commuter ask, newborn participates immediately. After commuter asks update dynamic delays floor((250/rate)/(ticks-lastHere+1)*base), sentinel lastHere0 ->floor(base/2). Middle close waits until route2 empty. Three exact route algorithms/tie rules below; source greedy no-middle can divide0 or fractional power negative. Completed travel=(ticks-birth)/450, average EWMA1/20, route average1/smoothing; cars-spawned cumulative despite comment active. No stop.', 'cash-flow': 'Wrapped17x17,473 people, wallet random2*10 (0 or10), savings/loans0. Entire business random sequential phase, then separate random sequential balance-books/color phase, then ONE bank balance sheet and classes then tick. Movement integer random360. Deposit/withdraw loans and repayment explicit source operations, bank-to-loan stale between balance phases except loan/repay updates. Source negative available-to-loan is passed into take-out-a-loan, can decrease loans: preserve and expose, no silent clamp. Balance reserves=percent*deposits; toLoan=deposits-reserves-loans. Wealth=savings-loans excludes wallet. Rich/poor thresholds>10, class count can overlap. All source sums/plots below. People setup, reserves live; no stop.', 'bank-reserves': 'Wrapped17x17,57 people, wallet random10+1. Distinct from Cash Flow: three ticks per cycle: ticks%3==0 business,==1 balance+shape,==2 EACH TURTLE calls bank sheet. Classes counted BEFORE phase, initial classes all0. Random-float360 movement. Negative available loan behavior same as source and explicitly preserved. Shape/color only sets green/red over previous blue/color and does not reset middle to gray. Wealth excludes wallets. Bank aggregates may lag; zero people means bank sheet ask never executes. Reserve percent live; people setup-only. No stop. Native histogram50/1 bins and income/savings/money histories specified below.', 'prisoners-dilemma-basic': 'Hard35x35 no simulation clock: setup draws face and samples partner unless known. answer ALWAYS calls setup, then four outcomes: both silent1, you confess/partner silent0, you silent/partner confesses5, both confess3 years. Known partner/default switches below. User message adapted as persistent accessible result; repeated Step/Run means repeated independent answer actions, never implied iterated strategy. No source reporters/plots/tick; target action count must be labeled host rounds, native clock absent.', 'prisoners-dilemma-two-person-iterated': 'Hard35x17 two players. Setup scores3, all defect flags false, choose hidden strategy uniformly seven choices; custom exactly tit-for-tat. User strategy then computer strategy from previous partner memory, both actions computed BEFORE payoffs. Payoff mutualC3,temptation5,sucker0,mutualD1. Update previous/two-round memories, score then tick. Average precision(score/(ticks+1),3) includes initial3 pseudo-round. Unforgiving uses partnerLast OR ownLast flag. Live chosen/hidden strategy switch and display-history. No stop. Prepare-next after setup describes cooperative initial state. Source cumulative scores monitors and average histories remain distinct.', 'el-farol': 'Wrapped35x35,100 agents, memory5/10 strategies, threshold60. History starts2*memory random100 values; attendance first history although agents placed at home. Weights memory+1 in[-1,1], intercept100*w0, dot product past attendance; no clamp. Score sum absolute errors back memory weeks; initial bestScore=memory*100+1 (not infinity), <= ties last wins; if all exceed threshold retains previous strategy. After selection prediction is LAST scored strategy/week, not necessarily chosen strategy prediction. Predict all agents from common old history then random sequential relocation, attendance count bar, crowded iff>threshold, history prepend/drop, select strategies then tick. Unique occupancy presentation location has no behavioral meaning. Threshold live; memory/number strategies setup-bound to avoid inconsistent vector lengths; report source changing-memory errors if exercised. No terminal condition.'}
report=['# Selected economics exact served source audit','',f"Inventory Galapagos revision `{inv['upstream']['galapagos']}`. Archived research originals copied only after SHA-256, byte count and pinned Git blob match. Desktop membership is not Web catalog membership. No new literature pass.",'']
evidence=[]
for slug in slugs:
 row=next(r for r in inv['rows'] if r.get('scope',{}).get('experimentSlug')==slug)
 data=(Path('docs/research/netlogo-web/evidence/social-urban')/(slug+'.nlogox')).read_bytes()
 sha=hashlib.sha256(data).hexdigest(); blob=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
 assert sha==row['sha256'] and len(data)==row['bytes'] and blob==tree[row['catalogKey']+'.nlogox']['sha']==row['galapagos']['blobSha1']
 root=E.fromstring(data); dest=Path('experiments')/slug; dest.mkdir(exist_ok=True); (dest/'source.nlogox').write_bytes(data)
 provenance={k:row[k] for k in ['id','sourceUrl','sha256','bytes','gitBlobSha1','galapagos','netlogoVersion','extensions','includes']}
 (dest/'source.json').write_text(json.dumps(provenance,indent=2)+'\n')
 (dest/'NOTICE.md').write_text(f"# {row['name']} provenance\n\nCanonical selected path: `{row['id']}`.\n\nExact served source: {row['sourceUrl']}\n\nSHA-256 `{sha}`; {len(data)} bytes; Git blob `{blob}`. Pinned Galapagos `{inv['upstream']['galapagos']}`.\n\n## Citation\n\n{row.get('citationNotice','')}\n\n## Credits\n\n{row.get('creditsNotice','')}\n\n## Copyright and license\n\n{row['licenseNotice']}\n\n## Adaptation\n\nReadable headless TypeScript composition using public City Library operations; independent Mulberry RNG, no cross-engine seeded trajectory identity. Native source is retained unchanged. Procedure/order and browser adaptations are tracked in selected-economics reports. Research is not empirical validation.\n")
 report += [f"## {row['name']}",'',f"Canonical path: `{row['id']}`. Source URL: {row['sourceUrl']}. SHA-256 `{sha}`; bytes {len(data)}; Git blob `{blob}`. Includes `{row['includes']}`; extensions `{row['extensions']}`.",'','### Binding semantic audit','',notes[slug],'','### Exact widgets, defaults, plots and actions','', '```xml',E.tostring(root.find('widgets'),encoding='unicode'),'```','','### Exact named procedures and equations','','```netlogo',root.findtext('code'),'```','']
 evidence.append({'slug':slug,**provenance,'archiveMatchesInventoryAndPinnedBlob':True})
Path('docs/development/selected-economics-source-audit.md').write_text('\n'.join(report))
Path('docs/development/selected-economics-evidence/source-validation.json').write_text(json.dumps(evidence,indent=2)+'\n')
print('Validated and archived',len(evidence),'exact XML originals')
